class Solution:
    def countAnagrams(self, s: str) -> int:
        words = s.split()
        ans = 1
        for word in words:
            freq = {}
            for ch in word:
                freq[ch] = freq.get(ch, 0) + 1
            duplicates = 1
            for f in freq.values():
                duplicates *= math.factorial(f)
            cur = math.factorial(len(word)) // duplicates
            ans = (ans * cur) % mod
        return ans

