class Solution:
    def longestWPI(self, A):
        curr, ans, D = 0, 0, {}
        for e, v in enumerate(map(lambda x: (-1, 1)[x > 8], A)):
            curr += v
            # store the earliest index for each prefix sum
            if curr not in D:
                D[curr] = e
            if curr > 0:
                ans = e + 1                 # subarray from start is longest so far
            else:
                # longest subarray ending at e is from the earliest index with a smaller prefix sum
                ans = max(ans, e - D.get(curr - 1, e))
        return ans

