class Solution:
    def maxDistance(self, nums1: List[int], nums2: List[int]) -> int:
        def farthest_ge(target: int, start: int) -> int:
            """Return the farthest index j >= start where nums2[j] >= target.
            Returns -1 if no such index exists."""
            left, right = start, len(nums2) - 1
            ans = -1
            while left <= right:
                mid = (left + right) // 2
                if nums2[mid] >= target:
                    ans = mid
                    left = mid + 1
                else:
                    right = mid - 1
            return ans

        maxDiff = 0
        for i in range(len(nums1)):
            if nums1[i] > nums2[-1]:
                continue
            j = farthest_ge(nums1[i], i)
            if j != -1:
                maxDiff = max(maxDiff, j - i)
        return maxDiff

